import {
  ALPHABET_LETTER_TO_SLUG,
  ALPHABET_REPLACEMENT_CHAR,
  obfuscateStringFromAvailableLetters,
} from "@hunt/alpha-round";
import { COPY_ONLY_CLASS, NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { HorizontalDivider } from "@hunt/puzzle-components";
import {
  Button,
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React, { useEffect, useState } from "react";
import stop from "./assets/stop.svg";
import { GENERATION_DATA } from "./generationData";

export function formatLine(parts: string[]): React.ReactNode[] {
  return parts.map((segment, idx) => {
    const charCount = Array.from(segment).length; // 1 or 7
    const isStop = segment === "🛑";
    const isWide = charCount === 7;
    if (isStop) {
      return (
        <img
          key={idx}
          src={stop}
          alt={segment}
          draggable="false"
          className="inline-block w-[1.6ch] h-auto direct-alt -translate-y-[1px]"
        />
      );
    }

    return (
      <span
        key={idx}
        className={cn(
          "inline-block text-center",
          isWide ? "w-[7.6ch]" : "w-[1.6ch]",
        )}
      >
        {segment}
      </span>
    );
  });
}

const monoStyle = {
  fontFamily:
    "'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace",
};

const SOLVED_LETTERS_KEY = "hunt.land_of_no_name.solved_letters";
const SHOW_ALL_LETTERS_KEY = "hunt.land_of_no_name.show_all_letters";
const LOCAL_STATE_EVENT = "land-of-no-name-local-state";
const ALL_LETTERS = Object.keys(ALPHABET_LETTER_TO_SLUG).sort();

const parseStoredLetters = (raw: string | null): string[] => {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((entry) => (typeof entry === "string" ? entry.toUpperCase() : ""))
      .filter((entry) => /^[A-Z]$/.test(entry));
  } catch {
    return [];
  }
};

const getAvailableLetters = (): string[] => {
  if (typeof window === "undefined" || !window.localStorage) {
    return [];
  }
  try {
    if (window.localStorage.getItem(SHOW_ALL_LETTERS_KEY) === "true") {
      return ALL_LETTERS;
    }
    return parseStoredLetters(window.localStorage.getItem(SOLVED_LETTERS_KEY));
  } catch {
    return [];
  }
};

const obfuscateSegment = (segment: string, availableLetters: string[]) => {
  if (segment === "🛑") return segment;
  if (availableLetters.length === 0) {
    return segment.replace(/[A-Za-z]/g, ALPHABET_REPLACEMENT_CHAR);
  }
  return obfuscateStringFromAvailableLetters(segment, availableLetters);
};

export const DataComponent = ({ text }: { text: string }) => {
  const [left, setLeft] = useState("1");
  const [right, setRight] = useState("1");
  const [output, setOutput] = useState<string[][][]>([
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
    [],
  ]);
  const [lastCheckTime, setLastCheckTime] = useState<number>(0);
  const [availableLetters, setAvailableLetters] = useState<string[]>(() =>
    getAvailableLetters(),
  );

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }
    const sync = () => {
      setAvailableLetters(getAvailableLetters());
    };
    const handleStorage = (event: StorageEvent) => {
      if (
        event.key === SOLVED_LETTERS_KEY ||
        event.key === SHOW_ALL_LETTERS_KEY
      ) {
        sync();
      }
    };
    window.addEventListener(LOCAL_STATE_EVENT, sync);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(LOCAL_STATE_EVENT, sync);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const addData = (x: number, ind: number) => {
    if (Date.now() < lastCheckTime + 200) {
      return;
    }
    setLastCheckTime(Date.now());
    const source = GENERATION_DATA[ind];
    if (!source) return;
    const rows = Array.from({ length: x }, () =>
      source.map((choices) => {
        const pick = choices[Math.floor(Math.random() * choices.length)];
        return pick;
      }),
    );
    setOutput((y) => y.map((i, ind2) => (ind === ind2 ? i.concat(rows) : i)));
  };

  const obfuscateLine = (line: string[]) =>
    line.map((segment) => obfuscateSegment(segment, availableLetters));

  return (
    <div>
      <div className={`flex items-center space-x-2 ${NO_COPY_CLASS}`}>
        <span>{text}</span>
        <Button
          variant="primary"
          onClick={() => {
            addData(1, 0);
          }}
        >
          +1
        </Button>
        <Button
          variant="primary"
          onClick={() => {
            addData(10, 0);
          }}
        >
          +10
        </Button>
      </div>
      <p>{text}:</p>
      <details open className={NO_COPY_CLASS}>
        <summary></summary>
        <ul style={monoStyle}>
          {output[0].map((i, ind) => (
            <li key={ind}>{formatLine(obfuscateLine(i))}</li>
          ))}
        </ul>
      </details>
      <table className={`font-mono ${COPY_ONLY_CLASS}`}>
        {output[0].map((i, ind) => (
          <tr key={ind}>
            {obfuscateLine(i).map((j, ind2) => (
              <td key={ind2}>{j}</td>
            ))}
          </tr>
        ))}
      </table>
      <HorizontalDivider />
      <div className={`flex items-center space-x-2 ${NO_COPY_CLASS}`}>
        <Select value={left} onValueChange={setLeft}>
          <SelectTrigger className="w-[80px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="1">1</SelectItem>
            <SelectItem value="2">2</SelectItem>
            <SelectItem value="3">3</SelectItem>
          </SelectContent>
        </Select>
        <span className="text-lg">+</span>
        <Select value={right} onValueChange={setRight}>
          <SelectTrigger className="w-[80px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="1">1</SelectItem>
            <SelectItem value="2">2</SelectItem>
            <SelectItem value="3">3</SelectItem>
          </SelectContent>
        </Select>
        <Button
          variant="primary"
          onClick={() => {
            addData(1, 3 * parseInt(left) + parseInt(right) - 3);
          }}
        >
          +1
        </Button>
        <Button
          variant="primary"
          onClick={() => {
            addData(10, 3 * parseInt(left) + parseInt(right) - 3);
          }}
        >
          +10
        </Button>
      </div>

      <div className={NO_COPY_CLASS}>
        <p className="pt-2">
          {left} + {right}:
        </p>

        <details open>
          <summary></summary>
          <ul style={monoStyle}>
            {output[3 * parseInt(left) + parseInt(right) - 3].map((i, ind) => (
              <li key={ind}>{formatLine(obfuscateLine(i))}</li>
            ))}
          </ul>
        </details>
      </div>

      <div className={COPY_ONLY_CLASS}>
        {["1", "2", "3"].map((left, ind1) => (
          <React.Fragment key={ind1}>
            {["1", "2", "3"].map((right, ind2) => (
              <React.Fragment key={ind2}>
                <p>
                  {left} + {right}:
                </p>

                <table className="font-mono">
                  {output[3 * parseInt(left) + parseInt(right) - 3].map(
                    (i, ind) => (
                      <tr key={ind}>
                        {obfuscateLine(i).map((j, ind2) => (
                          <td key={ind2}>{j}</td>
                        ))}
                      </tr>
                    ),
                  )}
                </table>
              </React.Fragment>
            ))}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};
