import React from "react";
import { createRoot } from "react-dom/client";
import { DataComponent } from "./DataComponent";

const elem = document.getElementById("puzzle-root");
const skipMount = (
  window as unknown as { landOfNoNameClientRendered?: boolean }
).landOfNoNameClientRendered;
if (elem && !skipMount) {
  const text = (window as unknown as { dataText: string }).dataText;
  const root = createRoot(elem);
  root.render(<DataComponent text={text} />);
} else {
  if (!elem && !skipMount) {
    console.error(
      "Could not mount App because #puzzle-root was nowhere to be found",
    );
  }
}
